def _visible_lines(markdown: str) -> list[tuple[int, str]]:
    visible: list[tuple[int, str]] = []
    fence: str | None = None
    for line_number, raw in enumerate(markdown.splitlines(), start=1):
        stripped = raw.lstrip()
        marker = stripped[:3]
        if marker in {"```", "~~~"}:
            if fence is None:
                fence = marker
            elif marker == fence:
                fence = None
            continue
        if fence is None:
            visible.append((line_number, raw))
    return visible

def _headings(markdown: str) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for line_number, line in _visible_lines(markdown):
        match = _HEADING_RE.match(line.strip())
        if match:
            result.append({"level": len(match.group(1)), "text": match.group(2).strip(), "line": line_number})
    return result

def _section_bodies(markdown: str, headings: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    lines = markdown.splitlines()
    result: list[dict[str, Any]] = []
    for index, heading in enumerate(headings):
        start = int(heading["line"])
        end = len(lines)
        for following in headings[index + 1 :]:
            if int(following["level"]) <= int(heading["level"]):
                end = int(following["line"]) - 1
                break
        result.append({**heading, "body": "\n".join(lines[start:end]).strip()})
    return result

def _matches_section(heading: Mapping[str, Any], section: SectionContract) -> bool:
    if int(heading["level"]) != section.level:
        return False
    value = str(heading["text"])
    if section.heading_pattern:
        return re.fullmatch(section.heading_pattern, value) is not None
    return value == section.heading

def _effective_budget(
    budget: CountBudget,
    contract: HumanPageTemplateContract,
    headings: Sequence[Mapping[str, Any]],
) -> tuple[int, int, int]:
    units = 1
    if budget.scope == "entry":
        entry = next((section for section in contract.required_sections if section.section_id == "entry"), None)
        if entry is None:
            raise RuntimeError(f"entry-scoped budget has no entry section: {contract.page_type}")
        units = max(1, sum(1 for heading in headings if _matches_section(heading, entry)))
    return budget.minimum * units, budget.maximum * units, units

def _context_sequence(context: Mapping[str, Any], name: str, errors: list[dict[str, Any]]) -> list[Any]:
    value = context.get(name, [])
    if not isinstance(value, list):
        errors.append(_validation_error("validation-context-invalid", f"validation context 的 {name} 必须是数组。", field=name))
        return []
    return value

def _link_occurrences(markdown: str) -> list[dict[str, Any]]:
    text = "\n".join(line for _line_number, line in _visible_lines(markdown))
    links: list[dict[str, Any]] = []
    for match in _INLINE_LINK_RE.finditer(text):
        links.append({"label": match.group(1).strip(), "target": match.group(2).strip()})
    for match in _WIKILINK_RE.finditer(text):
        target = match.group(1).strip()
        alias = (match.group(2) or "").strip()
        links.append({"label": alias or target, "target": target})
    return links

def _normalized_text_list(value: Any, field: str, errors: list[dict[str, Any]]) -> list[str]:
    if not isinstance(value, list):
        errors.append(_validation_error("validation-context-invalid", f"{field} 必须是数组。", field=field))
        return []
    result: list[str] = []
    for index, item in enumerate(value):
        if not isinstance(item, str) or not item.strip():
            errors.append(_validation_error("validation-context-invalid", f"{field} 只能包含非空字符串。", field=f"{field}[{index}]"))
            continue
        result.append(item.strip())
    return result

def _load_context(path: Path | None) -> Mapping[str, Any]:
    if path is None:
        return {}
    try:
        value = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        raise CkbError(f"模板 validation context 不是有效 JSON：{path}：{exc}") from exc
    if not isinstance(value, Mapping):
        raise CkbError(f"模板 validation context 必须是 JSON 对象：{path}")
    return value

def main(argv: Sequence[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        if args.command == "registry":
            print(
                serialize_human_page_template_registry(
                    contract_version=args.contract_version,
                    schema_version=args.schema_version,
                ),
                end="",
            )
            return 0
        if args.command == "get":
            contract = get_human_page_template(
                args.page_type,
                contract_version=args.contract_version,
                schema_version=args.schema_version,
            )
            result = {
                "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
                "page_type": human_page_template_document(contract),
                "registry_sha256": human_page_template_registry_sha256(),
                "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
                "status": "ready",
            }
            print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
            return 0
        markdown = args.input.read_text(encoding="utf-8-sig")
        result = validate_human_page(
            args.page_type,
            markdown,
            context=_load_context(args.context),
            contract_version=args.contract_version,
            schema_version=args.schema_version,
        )
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if result["status"] == "passed" else 2
    except (CkbError, OSError, UnicodeError) as exc:
        result = {
            "contract_version": getattr(args, "contract_version", HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION),
            "errors": [_validation_error("command-input-invalid", str(exc))],
            "schema_version": getattr(args, "schema_version", HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION),
            "status": "failed",
        }
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 2

def _text_list(value: Any, name: str, maximum: int = 32) -> list[str]:
    if not isinstance(value, list) or not value or len(value) > maximum:
        raise CkbError(f"keyword benchmark {name} must contain 1 to {maximum} strings")
    if any(not isinstance(item, str) or not item.strip() or len(item) > 512 for item in value):
        raise CkbError(f"keyword benchmark {name} contains an invalid string")
    return [item.strip() for item in value]

def load_keyword_benchmark(path: Path) -> list[dict[str, Any]]:
    value = json_load(path.resolve())
    if not isinstance(value, dict) or set(value) != {"schema_version", "cases"}:
        raise CkbError("keyword benchmark file must contain only schema_version and cases")
    if value.get("schema_version") != KEYWORD_BENCHMARK_SCHEMA_VERSION:
        raise CkbError("keyword benchmark schema version mismatch")
    cases = value.get("cases")
    if not isinstance(cases, list) or not 1 <= len(cases) <= MAX_BENCHMARK_CASES:
        raise CkbError(f"keyword benchmark must contain 1 to {MAX_BENCHMARK_CASES} cases")
    normalized: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in cases:
        if not isinstance(item, dict):
            raise CkbError("keyword benchmark cases must be objects")
        allowed = {"id", "question", "expected_names", "expected_source_paths", "budget", "max_pages", "profile"}
        if set(item) - allowed:
            raise CkbError("keyword benchmark case contains unsupported fields")
        case_id = item.get("id")
        if not isinstance(case_id, str) or not _CASE_ID.fullmatch(case_id) or case_id in seen:
            raise CkbError("keyword benchmark case id must be unique and bounded")
        seen.add(case_id)
        question = item.get("question")
        if not isinstance(question, str) or not question.strip() or len(question) > 12_000:
            raise CkbError("keyword benchmark question must contain 1 to 12000 characters")
        budget = item.get("budget", 1800)
        max_pages = item.get("max_pages", 8)
        profile = item.get("profile", "fast")
        if isinstance(budget, bool) or not isinstance(budget, int) or not 200 <= budget <= 1_000_000:
            raise CkbError("keyword benchmark budget must be an integer in [200, 1000000]")
        if isinstance(max_pages, bool) or not isinstance(max_pages, int) or not 1 <= max_pages <= 32:
            raise CkbError("keyword benchmark max_pages must be an integer in [1, 32]")
        if profile not in {"fast", "precise"}:
            raise CkbError("keyword benchmark profile must be fast or precise")
        normalized.append(
            {
                "id": case_id,
                "question": question.strip(),
                "expected_names": _text_list(item.get("expected_names"), "expected_names"),
                "expected_source_paths": _text_list(item.get("expected_source_paths"), "expected_source_paths"),
                "budget": budget,
                "max_pages": max_pages,
                "profile": profile,
            }
        )
    return normalized

def _location(result: dict[str, Any], expected_names: list[str], expected_paths: list[str]) -> dict[str, Any]:
    selected = result.get("selected_entities") or []
    names = {
        str(value).casefold()
        for item in selected
        for value in (item.get("name"), item.get("qualified_name"))
        if value
    }
    paths = {str(item.get("source_path")).casefold() for item in selected if item.get("source_path")}
    expected_name_ids = {value.casefold() for value in expected_names}
    expected_path_ids = {value.replace("\\", "/").casefold() for value in expected_paths}
    matched_names = sorted(value for value in expected_names if value.casefold() in names)
    matched_paths = sorted(
        value
        for value in expected_paths
        if value.replace("\\", "/").casefold() in {path.replace("\\", "/") for path in paths}
    )
    total = len(expected_name_ids) + len(expected_path_ids)
    matched = len(matched_names) + len(matched_paths)
    return {
        "score": round(matched / total, 6) if total else 0.0,
        "matched_names": matched_names,
        "matched_source_paths": matched_paths,
        "selected_entities": len(selected),
        "selected_source_paths": len(paths),
        "estimated_tokens": result.get("estimated_tokens"),
        "status": result.get("status"),
    }

def keyword_cache_key(question: str, config: KeywordProviderConfig) -> str:
    validate_provider_config(config)
    material = {
        "input_hash": keyword_input_hash(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
    }
    serialized = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("ascii")).hexdigest()

def _machine_token(value: Any, name: str) -> str:
    if not isinstance(value, str) or not _MACHINE_TOKEN.fullmatch(value):
        raise CkbError(f"keyword provider {name} must be a bounded machine token")
    return value

def validate_provider_config(config: KeywordProviderConfig) -> None:
    if not config.command or any(not isinstance(value, str) or not value for value in config.command):
        raise CkbError("keyword provider command must contain at least one non-empty argument")
    _machine_token(config.provider, "provider")
    _machine_token(config.model, "model")
    _machine_token(config.version, "version")
    if not 0.1 <= config.timeout_seconds <= 300.0:
        raise CkbError("keyword provider timeout must be between 0.1 and 300 seconds")
    if config.retries not in {0, 1}:
        raise CkbError("keyword provider retries must be zero or one")
    for name in config.required_environment:
        if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,127}", name):
            raise CkbError("keyword provider required environment names must be bounded identifiers")

def _bounded_strings(
    value: Any,
    *,
    name: str,
    maximum_items: int,
    maximum_chars: int,
    pattern: re.Pattern[str],
) -> list[str]:
    if not isinstance(value, list) or len(value) > maximum_items:
        raise CkbError(f"keyword provider {name} must be an array with at most {maximum_items} items")
    result: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, str):
            raise CkbError(f"keyword provider {name} items must be strings")
        normalized = item.strip()
        if not normalized or len(normalized) > maximum_chars:
            raise CkbError(f"keyword provider {name} items must contain 1 to {maximum_chars} characters")
        if not pattern.fullmatch(normalized):
            raise CkbError(f"keyword provider {name} contains unsupported characters")
        if _PROMPT_INJECTION.search(normalized):
            raise CkbError(f"keyword provider {name} contains prompt-injection text")
        if _CREDENTIAL_SHAPE.search(normalized):
            raise CkbError(f"keyword provider {name} contains credential-shaped text")
        identity = normalized.casefold()
        if identity in seen:
            raise CkbError(f"keyword provider {name} contains duplicate items")
        seen.add(identity)
        result.append(normalized)
    return result

def _usage(value: Any) -> dict[str, Any]:
    if value is None:
        value = {}
    if not isinstance(value, dict):
        raise CkbError("keyword provider usage must be an object")
    allowed = {"input_tokens", "output_tokens", "total_tokens", "cost_usd"}
    if set(value) - allowed:
        raise CkbError("keyword provider usage contains unsupported fields")
    result: dict[str, Any] = {}
    for name in ("input_tokens", "output_tokens", "total_tokens"):
        item = value.get(name, 0)
        if isinstance(item, bool) or not isinstance(item, int) or item < 0:
            raise CkbError(f"keyword provider usage {name} must be a non-negative integer")
        result[name] = item
    cost = value.get("cost_usd", 0.0)
    if isinstance(cost, bool) or not isinstance(cost, (int, float)) or cost < 0:
        raise CkbError("keyword provider usage cost_usd must be a non-negative number")
    result["cost_usd"] = round(float(cost), 8)
    if result["total_tokens"] and result["total_tokens"] != result["input_tokens"] + result["output_tokens"]:
        raise CkbError("keyword provider usage total_tokens does not match input plus output")
    return result

def parse_provider_json(raw: str) -> Any:
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise CkbError("keyword provider returned invalid JSON") from exc
